//! Palette reduction: a swatch list becomes a ramp.
//!
//! A palette already is an ordered set of colors, so the reduction is close to
//! the input: sort the swatches by hue, then by brightness, and paint them into
//! a grid. Two palettes with the same colors in a different order reduce to the
//! same picture, which is what you want when the file is generated by a tool.

use image::{Rgb, RgbImage};
use lab_core::medium::Medium;
use lab_core::reducer::{ReduceError, Reducer, Tier};

use crate::finish_canvas;

/// Most swatches an input may contribute. Above this the ramp is sampled,
/// because a grid finer than one screen pixel has nothing left to show.
const MAX_SWATCHES: usize = 4096;

/// The color of a cell with no swatch in it.
const BG: Rgb<u8> = Rgb([16, 16, 16]);

/// The palette tier: parse swatches, sort them, paint a ramp.
#[derive(Clone, Debug, Default)]
pub struct PaletteReducer {
    pub crop: lab_core::CropScale,
}

impl PaletteReducer {
    pub fn new(crop: lab_core::CropScale) -> Self {
        Self { crop }
    }
}

impl Reducer for PaletteReducer {
    fn tier(&self) -> Tier {
        Tier::Palette
    }

    fn reduce(&self, input: &[u8], side: u32) -> Result<Medium, ReduceError> {
        let swatches = swatches(input)?;
        let (canvas, size) = swatch_canvas(&swatches);
        let mut img = RgbImage::from_pixel(size, size, BG);
        for (i, c) in canvas.iter().enumerate() {
            let Some(c) = c else { continue };
            let x = (i as u32) % size;
            let y = (i as u32) / size;
            img.put_pixel(x, y, Rgb(*c));
        }
        finish_canvas(Tier::Palette, img, &self.crop, side)
    }
}

/// Parse, cap and sort the swatches. Sorting by hue here, not in the reducer,
/// so the export moves the same order the picture shows.
pub(crate) fn swatches(input: &[u8]) -> Result<Vec<[u8; 3]>, ReduceError> {
    if input.is_empty() {
        return Err(ReduceError::Empty(Tier::Palette));
    }
    let mut swatches = parse(input).map_err(ReduceError::Decode)?;
    if swatches.is_empty() {
        return Err(ReduceError::Empty(Tier::Palette));
    }
    if swatches.len() > MAX_SWATCHES {
        let step = swatches.len() as f64 / MAX_SWATCHES as f64;
        swatches = (0..MAX_SWATCHES)
            .map(|i| swatches[(i as f64 * step) as usize])
            .collect();
    }
    swatches.sort_by(|a, b| {
        key(*a)
            .partial_cmp(&key(*b))
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    Ok(swatches)
}

/// The swatches laid out in a square of `block`-sized squares, one entry per
/// canvas pixel, `None` in any gap.
pub(crate) fn swatch_canvas(swatches: &[[u8; 3]]) -> (Vec<Option<[u8; 3]>>, u32) {
    let n = swatches.len();
    let g = (n as f64).sqrt().ceil() as u32;
    let block = (512 / g.max(1)).max(1);
    let size = g * block;
    let mut out = vec![None; (size * size) as usize];
    for (i, c) in swatches.iter().enumerate() {
        let x = (i as u32 % g) * block;
        let y = (i as u32 / g) * block;
        for dy in 0..block {
            for dx in 0..block {
                out[((y + dy) * size + x + dx) as usize] = Some(*c);
            }
        }
    }
    (out, size)
}

/// The sort key: hue first, then value, so a palette reads as a spectrum from
/// cold to warm rather than as its file order.
fn key(c: [u8; 3]) -> (f32, f32) {
    let max = c[0].max(c[1]).max(c[2]) as f32;
    let min = c[0].min(c[1]).min(c[2]) as f32;
    let d = max - min;
    let (r, g, b) = (c[0] as f32, c[1] as f32, c[2] as f32);
    let hue = if d < 1.0 {
        0.0
    } else if max == r {
        ((g - b) / d).rem_euclid(6.0)
    } else if max == g {
        (b - r) / d + 2.0
    } else {
        (r - g) / d + 4.0
    };
    (hue, max / 255.0)
}

fn parse(source: &[u8]) -> Result<Vec<[u8; 3]>, String> {
    if source.starts_with(b"ASEF") {
        return parse_ase(source);
    }
    let text = String::from_utf8_lossy(source);
    if text.contains("GIMP Palette") {
        Ok(parse_gpl(&text))
    } else {
        Ok(parse_hex(&text))
    }
}

/// Inkscape `.hex`: one bare `RRGGBB` per line. A leading `#` is accepted, and
/// a line that is not six hex digits after it is treated as a comment.
fn parse_hex(text: &str) -> Vec<[u8; 3]> {
    let mut out = Vec::new();
    for line in text.lines() {
        let token = line
            .trim()
            .trim_start_matches('#')
            .split_whitespace()
            .next()
            .unwrap_or("");
        if let Some(c) = hex6(token) {
            out.push(c);
        }
    }
    out
}

/// GIMP `.gpl`: `R G B name` rows after a short header.
fn parse_gpl(text: &str) -> Vec<[u8; 3]> {
    let mut out = Vec::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut parts = line.split_whitespace();
        let triple = (|| {
            Some((
                parts.next()?.parse::<u8>().ok()?,
                parts.next()?.parse::<u8>().ok()?,
                parts.next()?.parse::<u8>().ok()?,
            ))
        })();
        if let Some((r, g, b)) = triple {
            out.push([r, g, b]);
        }
    }
    out
}

/// Adobe Swatch Exchange. Only the entry types that carry a color are read;
/// groups and the document trailer are skipped by their declared length.
fn parse_ase(bytes: &[u8]) -> Result<Vec<[u8; 3]>, String> {
    if bytes.len() < 12 {
        return Err("ASE file is shorter than its header".into());
    }
    let blocks = be_u32(bytes, 8) as usize;
    let mut out = Vec::new();
    let mut p = 12usize;
    for _ in 0..blocks {
        if p + 6 > bytes.len() {
            break;
        }
        let ty = be_u16(bytes, p);
        let len = be_u32(bytes, p + 2) as usize;
        let body = p + 6;
        let end = match body.checked_add(len) {
            Some(e) if e <= bytes.len() => e,
            _ => break,
        };
        if ty == 0x0001 {
            if let Some(c) = ase_color(bytes, body, end) {
                out.push(c);
            }
        }
        p = end;
    }
    if out.is_empty() {
        return Err("ASE file contains no RGB, gray or CMYK colors".into());
    }
    Ok(out)
}

fn ase_color(bytes: &[u8], start: usize, end: usize) -> Option<[u8; 3]> {
    if start + 2 > end {
        return None;
    }
    let name_len = be_u16(bytes, start) as usize;
    let model = start + 2 + name_len * 2;
    if model + 4 > end {
        return None;
    }
    let floats = match &bytes[model..model + 4] {
        b"RGB " => 3,
        b"Gray" => 1,
        b"CMYK" => 4,
        _ => return None,
    };
    if model + 4 + floats * 4 > end {
        return None;
    }
    let f = |off: usize| be_f32(bytes, model + 4 + off * 4);
    match &bytes[model..model + 4] {
        b"RGB " => Some([to_byte(f(0)), to_byte(f(1)), to_byte(f(2))]),
        b"Gray" => {
            let v = to_byte(f(0));
            Some([v, v, v])
        }
        _ => {
            let k = 1.0 - f(3);
            Some([gray(f(0), k), gray(f(1), k), gray(f(2), k)])
        }
    }
}

fn gray(c: f32, k: f32) -> u8 {
    to_byte((1.0 - c) * k)
}

fn to_byte(x: f32) -> u8 {
    (x.clamp(0.0, 1.0) * 255.0).round() as u8
}

fn hex6(s: &str) -> Option<[u8; 3]> {
    if s.len() != 6 {
        return None;
    }
    let byte = |i: usize| u8::from_str_radix(&s[i..i + 2], 16).ok();
    Some([byte(0)?, byte(2)?, byte(4)?])
}

fn be_u16(b: &[u8], i: usize) -> u16 {
    u16::from_be_bytes([b[i], b[i + 1]])
}

fn be_u32(b: &[u8], i: usize) -> u32 {
    u32::from_be_bytes([b[i], b[i + 1], b[i + 2], b[i + 3]])
}

fn be_f32(b: &[u8], i: usize) -> f32 {
    f32::from_be_bytes([b[i], b[i + 1], b[i + 2], b[i + 3]])
}
